namespace DofusTeamOrganizer.Models;

/// <summary>Succès de donjon d'un boss : niveau du donjon, jusqu'à 3 challenges, succès de groupe (Duo, Trio ou Quatuor), succès Spécial et page du donjon sur dofusyelle.com.</summary>
public record BossAch(string Boss, int Level, string[] Challenges, string GroupLabel, bool Special, string Slug, string SpecialName, string SpecialDesc)
{
    public string Url => "https://dofusyelle.com/donjons/" + Slug;
}

